        b = bearing_to(0.0, 0.0)
        fwd = 0.7
    elif d < 0.65:
        fwd = -0.4
    elif d < 1.1:
        fwd = 0.45
    else:
        fwd = 0.95

    if abs(b) > 120:
        fwd = 0.0

    if abs(b) > 90:
        turn = 1.0 if b > 0 else -1.0
    else:
        turn = b * 0.045

    if r > 5.6:
        cb = bearing_to(0.0, 0.0)
        if abs(cb) < 90:
            turn = (turn + cb * 0.04) * 0.5

