def steer(b, scale):
    if b > 18:
        left = 0.24
        right = 0.9
    elif b < -18:
        left = 0.9
        right = 0.24
    else:
        left = 0.78
        right = 0.78
    return (left * scale, right * scale)


def drive(me, enemy, arena):
    if me.righting or me.on_side or not me.can_drive:
        return (0, 0)

    if me.held or me.lifted:
        return (0.8, 0.8)

    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)

    my_radius = sqrt(me.x * me.x + me.y * me.y)
    enemy_radius = sqrt(enemy.x * enemy.x + enemy.y * enemy.y)

    if my_radius > 4.95 and enemy_radius > my_radius - 0.15:
        inward = bearing_to(0, 0)
        return steer(inward, 0.72)

    if enemy.z > 0.12 and d < 1.5:
        if abs(b) > 135:
            return (0.45, 0.45)
        return (-0.45, -0.45)

    if abs(b) > 115 and d < 1.8:
        if b > 0:
            return (-0.25, 0.85)
        return (0.85, -0.25)

    if d < 0.85:
        scale = 0.42
    elif d < 1.4:
        scale = 0.62
    elif d < 2.2:
        scale = 0.82
    else:
        scale = 1.0

    return steer(b, scale)


